describe('Mobile Navigation Hamburger Menu', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Set viewport to mobile size
    });

    it('should display the hamburger menu when the screen is resized to mobile', () => {
        cy.get('.navbar').should('be.visible'); // Ensure the navbar is visible
        cy.get('.hamburger-menu').should('be.visible'); // Check if hamburger menu is visible
    });

    it('should collapse the navigation into a hamburger menu when clicked', () => {
        cy.get('.hamburger-menu').click(); // Click the hamburger menu
        cy.get('.navbar').should('not.be.visible'); // Ensure the navbar is collapsed
        cy.get('.hamburger-menu').should('have.class', 'active'); // Check if hamburger menu is active
    });
});
